-- =====================================================================
-- 0041_service_history.sql
--
-- The Seylan service sheets are right about every service they record -
-- they just haven't been kept up to date. So:
--
-- 1. Every recorded service becomes history: 340 services from
--    2024/25 (1st and 2nd service), 2025/26 and 2026/27, each marked done
--    with its date and service call number where the sheet has them. A
--    site listed twice for the same visit keeps the later one, with the
--    other noted. This gives every site its "last service".
-- 2. 2026/27, the current contract year: every active Seylan branch and
--    National Youth Corps centre with no 2026/27 service yet is Pending,
--    due by 31 Jul 2027 (Seylan: "1st service"; NYC: "Service"). If one
--    was done but not written in the sheet, mark it done, or import the
--    updated sheet.
--
-- Nothing already in the Service Plan is overwritten. Idempotent: safe to
-- re-run.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. Recorded services
-- ---------------------------------------------------------------------
INSERT INTO public.planned_services (site_id, contract_year, visit, status, done_at, service_call_number, notes)
SELECT s.id, v.contract_year, v.visit, 'done',
       CASE WHEN v.done IS NULL THEN NULL ELSE (v.done::date + time '12:00') AT TIME ZONE 'Asia/Colombo' END,
       v.service_call, v.notes
FROM (VALUES
  ('Kegalle', '2024/25', '1st service', '2024-09-02', NULL, 'From the Seylan service sheet (2024-25 row 4)'),
