  ('Mawanella', '2025/26', '1st service', '2026-08-24', '10531', 'From the Seylan service sheet (2025_26 row 119)'),
  ('Wennappuwa', '2025/26', '1st service', '2026-08-24', '10755', 'From the Seylan service sheet (2025_26 row 120)'),
  ('Dankotuwa', '2025/26', '1st service', '2026-08-24', '10754', 'From the Seylan service sheet (2025_26 row 121)'),
  ('Thalawathugoda', '2025/26', '1st service', '2026-08-19', '10753', 'From the Seylan service sheet (2025_26 row 122)'),
  ('Rajagiriya', '2025/26', '1st service', '2026-08-19', '10752', 'From the Seylan service sheet (2025_26 row 123)'),
  ('Katuneriya', '2025/26', '1st service', '2026-08-24', '10756', 'From the Seylan service sheet (2025_26 row 124)'),
  ('Old Moor Street', '2026/27', '1st service', '2026-09-08', '10764', 'From the Seylan service sheet (2026_27 row 3)'),
  ('Bambalapitiya', '2026/27', '1st service', '2026-09-10', '10573', 'From the Seylan service sheet (2026_27 row 4)'),
  ('Borella', '2026/27', '1st service', '2026-09-11', '10713', 'From the Seylan service sheet (2026_27 row 5)'),
  ('Gampaha', '2026/27', '1st service', '2026-09-11', '10770', 'From the Seylan service sheet (2026_27 row 6)'),
  ('Nugegoda', '2026/27', '1st service', '2026-09-15', '10771', 'From the Seylan service sheet (2026_27 row 7)'),
  ('Padukka', '2026/27', '1st service', '2026-09-16', '10778', 'From the Seylan service sheet (2026_27 row 8)'),
  ('Godagama', '2026/27', '1st service', '2026-09-16', '10777', 'From the Seylan service sheet (2026_27 row 9)')
) AS v(site, contract_year, visit, done, service_call, notes)
JOIN public.client_sites s ON s.client = 'Seylan Bank' AND s.name = v.site
ON CONFLICT (site_id, contract_year, visit) DO NOTHING;


-- ---------------------------------------------------------------------
-- 2. Due this contract year
-- ---------------------------------------------------------------------
INSERT INTO public.planned_services (site_id, contract_year, visit, due_by, notes)
SELECT s.id, '2026/27',
       CASE WHEN s.client = 'Seylan Bank' THEN '1st service' ELSE 'Service' END,
       DATE '2027-07-31',
       'Due for 2026/27: no service recorded yet this contract year.'
FROM public.client_sites s
WHERE s.client IN ('Seylan Bank', 'National Youth Corps')
  AND s.active
  AND NOT s.is_base
  AND NOT EXISTS (
    SELECT 1 FROM public.planned_services p WHERE p.site_id = s.id AND p.contract_year = '2026/27'
  )
ON CONFLICT (site_id, contract_year, visit) DO NOTHING;


-- ---------------------------------------------------------------------
-- 3. What there is now
-- ---------------------------------------------------------------------
SELECT s.client,
       count(DISTINCT s.id) AS sites,
       count(p.id) FILTER (WHERE p.status = 'done') AS services_done,
       count(p.id) FILTER (WHERE p.status = 'pending') AS pending,
       count(DISTINCT p.site_id) FILTER (WHERE p.status = 'done') AS sites_with_a_last_service
FROM public.client_sites s
LEFT JOIN public.planned_services p ON p.site_id = s.id
GROUP BY s.client
ORDER BY s.client;
